INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist ein Curved Screen nur für Gaming geeignet?', 2, '[{"text": "Nein", "correct": true, "because": "Auch für Büro und Multimedia"}, {"text": "Ja", "correct": false, "because": "Vielseitig einsetzbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Welchen Vorteil bietet mir ein gebogener Bildschirm?', 3, '[{"text": "Immersion", "correct": true, "because": "Breiteres Sichtfeld"}, {"text": "Höhere Auflösung", "correct": false, "because": "Nicht direkt damit verbunden"}, {"text": "Geringerer Preis", "correct": false, "because": "Oft teurer"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Technologien nutzen Curved Screens?', 5, '[{"text": "OLED", "correct": true, "because": "Flexibel biegbar"}, {"text": "LCD mit VA", "correct": true, "because": "Bessere Blickwinkel"}, {"text": "CRT", "correct": false, "because": "Veraltete Technik"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Curved Screens reduzieren Augenbelastung. b) Sie sind immer ultrabreit.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Nicht alle sind ultrabreit"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Wahl eines Curved Screens?', 4, '[{"text": "Krümmungsgrad", "correct": false, "because": "Beeinflusst Sicht"}, {"text": "Blickwinkel", "correct": false, "because": "Wichtig für Qualität"}, {"text": "Gehäusedesign", "correct": true, "because": "Sekundär zur Funktion"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Curved Screens immer teurer sind?', 2, '[{"text": "Nein", "correct": true, "because": "Preise variieren"}, {"text": "Ja", "correct": false, "because": "Nicht zwangsläufig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Größe ist für einen Curved Screen optimal?', 3, '[{"text": "34 Zoll", "correct": true, "because": "Gleichgewicht zwischen Immersion und Komfort"}, {"text": "15 Zoll", "correct": false, "because": "Zu klein"}, {"text": "60 Zoll", "correct": false, "because": "Zu groß für Nähe"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Einsatzbereiche profitieren davon?', 5, '[{"text": "Gaming", "correct": true, "because": "Immersion steigert Erlebnis"}, {"text": "Videoediting", "correct": true, "because": "Breitere Sichtfläche"}, {"text": "Serverwartung", "correct": false, "because": "Kein Vorteil"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Curved Screens bieten bessere Blickwinkel. b) Sie sind nur ein Gimmick. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Nutzen ist belegt"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für einen Curved Screen?', 4, '[{"text": "Hohe Auflösung", "correct": false, "because": "Verbessert Qualität"}, {"text": "Passender Stand", "correct": false, "because": "Ergonomie wichtig"}, {"text": "Externer Lautsprecher", "correct": true, "because": "Oft integriert"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Sind Curved Screens flach biegbar?', 2, '[{"text": "Nein", "correct": true, "because": "Fertigung gekrümmt"}, {"text": "Ja", "correct": false, "because": "Nicht flexibel"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aspekte verbessern die Erfahrung?', 4, '[{"text": "Krümmungsradius", "correct": true, "because": "Passt ans Sichtfeld"}, {"text": "Hoher Kontrast", "correct": true, "because": "Bessere Bildqualität"}, {"text": "Tastaturtyp", "correct": false, "because": "Kein Einfluss"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Curved Screens nur für TVs sind. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Auch Monitore und Phones"}, {"text": "Ja", "correct": false, "because": "Breitere Nutzung"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei der Auswahl?', 3, '[{"text": "Krümmung", "correct": true, "because": "Beeinflusst Immersion"}, {"text": "Gewicht", "correct": false, "because": "Sekundär"}, {"text": "Lautstärke", "correct": false, "because": "Nicht primär"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Sie passen zum menschlichen Auge. b) Sie sind immer 4K.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Auflösung variiert"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Nachteile könnten auftreten?', 5, '[{"text": "Verzerrung bei schrägem Blick", "correct": true, "because": "Außerhalb Sweet Spot"}, {"text": "Höherer Preis", "correct": true, "because": "Technologie teurer"}, {"text": "Schnellere CPU", "correct": false, "because": "Kein Einfluss"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei der Nutzung unwichtig?', 3, '[{"text": "Blickwinkel", "correct": false, "because": "Beeinflusst Qualität"}, {"text": "Auflösung", "correct": false, "because": "Wichtig für Klarheit"}, {"text": "Monitorhöhe", "correct": true, "because": "Ergonomie separat"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Reduzieren Curved Screens Reflexionen?', 3, '[{"text": "Ja", "correct": true, "because": "Krümmung lenkt Licht"}, {"text": "Nein", "correct": false, "because": "Nachweisbar reduziert"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Curved Screens für Gruppen geeignet sind?', 2, '[{"text": "Nein", "correct": true, "because": "Optimal für Einzelblick"}, {"text": "Ja", "correct": false, "because": "Sweet Spot begrenzt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Rolle spielt der Krümmungsgrad?', 4, '[{"text": "Beeinflusst Sichtfeld", "correct": true, "because": "Stärkere Krümmung immersiver"}, {"text": "Erhöht Lautstärke", "correct": false, "because": "Kein Audiofaktor"}, {"text": "Verkleinert Bild", "correct": false, "because": "Erweitert Wahrnehmung"}]');
